#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define VALID_MIN 0
#define VALID_MAX 1

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int value;
    struct timespec sleep_time = {5, 0}; // 5 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "my_gpio_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        // Generate a pseudo-random value (0 or 1)
        value = rand() % 2;

        // Validate the value
        if (value < VALID_MIN || value > VALID_MAX) {
            fprintf(stderr, "Error: Invalid value generated: %d\n", value);
            continue; // Skip setting the GPIO and sleeping
        }

        // Set GPIO output
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
        }

        // Report the state
        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        // Sleep for 5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    // Clean up GPIO resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d control stopped.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
