// MLX90614 I2C address
#define MLX90614_ADDR 0x5A

// Object temperature register address
#define MLX90614_TOBJ1 0x07

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read object temperature
        int raw_temp = i2cReadWordData(i2c_handle, MLX90614_TOBJ1);
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Convert raw temperature to Celsius
        float temperature = (float)raw_temp * 0.02 - 273.15;

        // Print temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

