#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int i;
    int duty_cycle;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("Driving PWM on GPIO %d (BCM) every 0.5 seconds...\n", GPIO_PIN);

    while (program_running) {
        // Sweep duty cycle from 0 to 1000000 in steps of 100000
        for (i = 0; i <= 1000000; i += 100000) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(500000); // 0.5 seconds
        }

        // Sweep duty cycle from 1000000 to 0 in steps of 100000
        for (i = 1000000; i >= 0; i -= 100000) {
            duty_cycle = i;
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            gpioDelay(500000); // 0.5 seconds
        }
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 100000       // Timeout in microseconds (100ms)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
double measure_distance(void);
void report_state(double distance);
void signal_handler(int sig);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Measure distance using HC-SR04
double measure_distance(void) {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger high\n");
        return -1.0;
    }
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1.0;
    }

    // Measure echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        if ((start.tv_sec - start.tv_sec) * 1000000 + (start.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            timeout = 1;
            break;
        }
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            timeout = 1;
            break;
        }
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    double distance = (pulse_width_ns / 1000.0) * SPEED_OF_SOUND / 2000000.0;

    return distance;
}

// Report the state to standard output
void report_state(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("%s, Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("%s, Error: Could not measure distance\n", timestamp);
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        double distance = measure_distance();
        report_state(distance);
        sleep(60);
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x28

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0040 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADS1115
int ads1115_init(int fd) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_QUE_DISABLE;
    uint8_t buf[3];

    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to config register");
        return -1;
    }

    return 0;
}

// Function to read a single sample from the ADS1115
int16_t ads1115_read(int fd) {
    uint8_t buf[1];
    uint8_t read_buf[2];
    int16_t value;

    // Start a single conversion
    buf[0] = ADS1115_REG_CONFIG;
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_QUE_DISABLE;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to start conversion");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    buf[0] = ADS1115_REG_CONVERT;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to conversion register");
        return -1;
    }

    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read conversion register");
        return -1;
    }

    value = (read_buf[0] << 8) | read_buf[1];
    return value;
}

// Function to validate the reading
int validate_reading(int16_t reading) {
    if (reading < -2048 || reading > 2047) {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to print the reading
void print_reading(int16_t reading) {
    printf("Reading: %d\n", reading);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t reading = ads1115_read(i2c_fd);
        if (reading != -1) {
            if (validate_reading(reading)) {
                print_reading(reading);
            }
        } else {
            fprintf(stderr, "Failed to read from ADS1115\n");
        }
        sleep(5);
    }

    return 0;
}

