    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return value;
}

// Function to report the state of a GPIO line
void report_gpio_state(struct gpiod_line *line) {
