#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x40
#define I2C_BUS 1
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from SI7021
float read_temperature() {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1000.0; // Indicate error
    }

    gpioDelay(30); // Wait for measurement (datasheet specifies 25ms for temp)

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1000.0; // Indicate error
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Function to read humidity from SI7021
float read_humidity() {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, HUMID_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1.0; // Indicate error
    }

    gpioDelay(30); // Wait for measurement (datasheet specifies 25ms for humidity)

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1.0; // Indicate error
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", humidity);
        return -1.0; // Indicate error
    }

    return humidity;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        float humidity = read_humidity();

        if (temperature > -999.0 && humidity > -0.5) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS, single-shot mode
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Take 3 readings
    for (int i = 0; i < 3; i++) {
        // Write configuration register
        if (write_i2c_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to write configuration register\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion register
        int16_t reading = read_i2c_word(i2c_fd, ADS1115_REG_CONVERT);
        if (reading < 0) {
            fprintf(stderr, "Failed to read conversion register\n");
            close(i2c_fd);
            return 1;
        }

        // Print the reading
        printf("Reading %d: %d\n", i + 1, reading);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins (BCM numbering)
const int gpio_pins[] = {8, 9, 10, 11, 23, 24};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for signal handling
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[6] = {NULL, NULL, NULL, NULL, NULL, NULL};
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to print the current state of all GPIO pins
void print_gpio_state(const int gpio_pins[], int num_pins, const int values[]) {
    for (int i = 0; i < num_pins; i++) {
        printf("GPIO %d: %d ", gpio_pins[i], values[i]);
    }
    printf("\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", gpio_pins[i]);
            goto cleanup;
        }

        // Request GPIO line for output
        struct gpiod_line_request_config config;
        config.consumer = "gpio_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        int ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %d\n", gpio_pins[i], ret);
            goto cleanup;
        }
    }

    // Main loop
    int cycle = 0;
    while (cycle < 256 && !terminate) {
        int values[num_pins];
        for (int i = 0; i < num_pins; i++) {
            values[i] = (cycle >> i) & 1;
            if (set_gpio_state(lines[i], values[i]) != 0) {
                goto cleanup;
            }
        }
        print_gpio_state(gpio_pins, num_pins, values);
        cycle++;
        usleep(10000); // 10ms delay
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_pins; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (terminate) {
        return 1;
    }

    return 0;
}

