#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN_NAME "gpio2"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, GPIO_PIN_NAME, 0); // Initial value 0
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        // Toggle GPIO output
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    printf("Exiting...\n");

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

