#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2, *line3;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return 0;
}

// Function to read GPIO value
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return value;
}

// Function to validate GPIO value
int validate_gpio_value(int value) {
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        return -1;
    }
