// Function to measure distance using HC-SR04
float measure_distance() {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_duration_ns;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger high\n");
        return -1.0;
    }
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1.0;
    }

    // Measure the echo pulse duration
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go high (with timeout)
    int timeout = 100000; // 100ms timeout
    while (gpiod_line_get_value(echo_line) == 0 && timeout > 0) {
        usleep(1); // Small delay to avoid busy-waiting
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go low (with timeout)
    timeout = 100000; // 100ms timeout
    while (gpiod_line_get_value(echo_line) == 1 && timeout > 0) {
        usleep(1); // Small delay to avoid busy-waiting
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_duration_ns = end_ns - start_ns;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_duration_ns * 0.000000001) * 34300 / 2
    // Simplified: distance = pulse_duration_ns * 0.000001715
    float distance = (float)pulse_duration_ns * 0.000001715;

    return distance;
}

