// Define GPIO pins to be used
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9, 17};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO line requests and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[9]; // Assuming a maximum of 9 pins
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    int ret;
    ret = gpiod_line_set_value(lines[pin], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", pin, state, gpiod_line_perror(lines[pin]));
        return -1;
    }
    return 0;
}

// Function to print the state of all GPIO pins
void print_gpio_states() {
    for (int i = 0; i < num_pins; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pins[i], gpiod_line_perror(lines[i]));
            continue; // Continue to the next pin
        }
        printf("GPIO %d: %d\n", gpio_pins[i], value);
    }
    printf("\n");
}

int main() {
    int i, ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_perror(chip));
        return 1;
    }

    // Get line requests for each GPIO pin
    for (i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", gpio_pins[i], gpiod_chip_perror(chip));
            goto cleanup;
        }

        // Request the line as an output
        ret = gpiod_line_request_output(lines[i], "gpio-control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d as output: %s\n", gpio_pins[i], gpiod_line_perror(lines[i]));
            goto cleanup;
        }
    }

    // Main loop to toggle GPIO pins
    while (program_running) {
        for (i = 0; i < num_pins; i++) {
            if (set_gpio_state(i, 1) != 0) goto cleanup;
        }
        print_gpio_states();
        usleep(50000); // 50ms

        for (i = 0; i < num_pins; i++) {
            if (set_gpio_state(i, 0) != 0) goto cleanup;
        }
        print_gpio_states();
        usleep(50000); // 50ms
    }

