#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

int i2c_fd = -1;

void signal_handler(int sig);
int opt3001_read(uint16_t *raw_data);
float opt3001_convert(uint16_t raw_data);

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int opt3001_read(uint16_t *raw_data) {
    uint8_t buffer[2];
    int ret;

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    return 0;
}

float opt3001_convert(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    return result * (0.01 * (1 << exponent));
}

int main() {
    uint16_t raw_data;
    float lux;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (opt3001_read(&raw_data) == 0) {
        lux = opt3001_convert(raw_data);
        printf("Lux: %.2f\n", lux);
    } else {
        fprintf(stderr, "Failed to read OPT3001 data.\n");
        close(i2c_fd);
        return 1;
    }

    close(i2c_fd);
    return 0;
}

