        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, BAUD_RATE) != 0 || cfsetispeed(&tty, BAUD_RATE) != 0) {
        fprintf(stderr, "Error setting baud rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout or no data available
        } else {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = configure_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "UART configuration failed. Exiting.\n");
        return 1;
    }

    char buffer[256];
    time_t start_time = time(NULL);

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        if (time(NULL) - start_time > TIMEOUT_SEC) {
            printf("Timeout reached. Exiting.\n");
            break;
        }

        usleep(100000); // 100ms delay
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return 0;
}

