#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define NUM_CYCLES 3
#define CYCLE_DURATION_SEC 60

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int set_gpio_output(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return 0;
}

int main() {
    int i, ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line as output */
    ret = gpiod_line_request_output(line, "my_gpio_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", gpiod_line_name(line));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    for (i = 0; i < NUM_CYCLES && !terminate; i++) {
        /* Set GPIO high */
        if (set_gpio_output(1) != 0) {
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);
        sleep(CYCLE_DURATION_SEC);

        /* Set GPIO low */
        if (set_gpio_output(0) != 0) {
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);
        sleep(CYCLE_DURATION_SEC);
    }

    /* Release GPIO line */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

