#define MAX_SENSORS 10
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"

// Structure to hold sensor information
typedef struct {
    char id[20];
    int valid;
} sensor_t;

// Global array to store sensor information
sensor_t sensors[MAX_SENSORS];
int num_sensors = 0;

// Function prototypes
int detect_sensors();
int read_temperature(const char *sensor_id, float *temperature);
int validate_temperature(float temperature);
void print_temperature(const char *sensor_id, float temperature);
void signal_handler(int signum);
int unexport_sensors();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        unexport_sensors();
        exit(0);
    }
}

// Function to detect DS18B20 sensors
int detect_sensors() {
    DIR *dir;
    struct dirent *ent;
    int count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && count < MAX_SENSORS) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensors[count].id, ent->d_name, sizeof(sensors[count].id) - 1);
            sensors[count].id[sizeof(sensors[count].id) - 1] = '\0'; // Ensure null termination
            sensors[count].valid = 1; // Initially mark as valid
            count++;
        }
    }

    closedir(dir);
    num_sensors = count;
    return 0;
}

// Function to read temperature from a sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, sensor_id, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening " W1_SLAVE_FILE);
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read == -1) {
        perror("Error reading " W1_SLAVE_FILE);
        return -1;
    }

    buffer[bytes_read] = '\0';

    // Parse the temperature from the w1_slave file
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Temperature data not found in %s\n", filepath);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

// Function to validate temperature reading
int validate_temperature(float temperature) {
    if (temperature < -50.0 || temperature > 125.0) {
        fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", temperature);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to print temperature reading
void print_temperature(const char *sensor_id, float temperature) {
    printf("Sensor: %s, Temperature: %.2f °C\n", sensor_id, temperature);
}

// Function to unexport sensors
int unexport_sensors() {
    for (int i = 0; i < num_sensors; i++) {
        char unexport_path[100];
        snprintf(unexport_path, sizeof(unexport_path), "/sys/bus/w1/drivers/w1-slave/unexport");

        int fd = open(unexport_path, O_WRONLY);
        if (fd == -1) {
            perror("Error opening unexport file");
            return -1;
        }

        if (write(fd, sensors[i].id, strlen(sensors[i].id)) == -1) {
            perror("Error writing to unexport file");
            close(fd);
            return -1;
        }

        close(fd);
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Detect sensors
    if (detect_sensors() != 0) {
        fprintf(stderr, "Error detecting sensors. Exiting.\n");
        return 1;
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            float temperature;
            if (read_temperature(sensors[i].id, &temperature) == 0) {
                if (validate_temperature(temperature)) {
                    print_temperature(sensors[i].id, temperature);
                } else {
                    sensors[i].valid = 0; // Mark as invalid
                }
            } else {
                sensors[i].valid = 0; // Mark as invalid
            }
        }
        sleep(5);
    }

    return 0;
}

