#define HTU21D_ADDR 0x40
#define TEMP_MEASURE_HOLD 0xE3
#define HUMID_MEASURE_HOLD 0xE5

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from HTU21D
int read_temperature(float *temperature) {
    char buf[3];
    int result;
    uint16_t raw_temp;

    result = i2cWriteByte(i2c_handle, TEMP_MEASURE_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet says 50ms)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    raw_temp &= 0xFFFC; // Clear status bits

    *temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    return 0;
}

// Function to read humidity from HTU21D
int read_humidity(float *humidity) {
    char buf[3];
    int result;
    uint16_t raw_humidity;

    result = i2cWriteByte(i2c_handle, HUMID_MEASURE_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement (datasheet says 50ms)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    raw_humidity = (buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC; // Clear status bits

    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    return 0;
}

