    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature\n");
        } else {
            // Read humidity
            if (read_humidity(&humidity) != 0) {
                fprintf(stderr, "Error reading humidity\n");
