        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(gpio->line) == 0) {
            // Timeout after a certain time
            usleep(1); // Check every microsecond
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine if it's a 0 or a 1 based on the duration
        if (duration > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
