void signal_handler(int sig) {
    stop_flag = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int tcs34725_init(int fd) {
    uint8_t id;
    uint8_t status;

    // Check device ID
    if (i2c_smbus_read_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ID) < 0) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    id = i2c_smbus_read_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id != 0x44) {
        fprintf(stderr, "Error: Incorrect ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    // Enable power and ALS
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON): %s\n", strerror(errno));
        return -1;
