    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
