#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_22 22
#define GPIO_PIN_27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line22;
static struct gpiod_line *line27;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 22 */
    line22 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    if (!line22) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_22);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get GPIO line for GPIO 27 */
    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);
    if (!line27) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_27);
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        return EXIT_FAILURE;
    }

    /* Request GPIO 22 as output */
    ret = gpiod_line_request_output(line22, "gpio22-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_PIN_22, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    /* Request GPIO 27 as output */
    ret = gpiod_line_request_output(line27, "gpio27-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_PIN_27, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (keep_running) {
        /* Set GPIO 22 high */
        ret = gpiod_line_set_value(line22, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %d\n", GPIO_PIN_22, ret);
            break;
        }
        printf("GPIO 22: HIGH\n");

        /* Set GPIO 27 low */
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %d\n", GPIO_PIN_27, ret);
            break;
        }
        printf("GPIO 27: LOW\n");

        usleep(10000); /* 10ms */

        /* Set GPIO 22 low */
        ret = gpiod_line_set_value(line22, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %d\n", GPIO_PIN_22, ret);
            break;
        }
        printf("GPIO 22: LOW\n");

        /* Set GPIO 27 high */
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %d\n", GPIO_PIN_27, ret);
            break;
        }
        printf("GPIO 27: HIGH\n");

        usleep(10000); /* 10ms */
    }

    /* Release GPIO lines */
    gpiod_line_release(line22);
    gpiod_line_release(line27);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

