// Initialize the SSD1306 display
int ssd1306_init(int fd) {
    // Initialization sequence (from Adafruit library)
    ssd1306_send_command(fd, 0xAE); // Display off
    ssd1306_send_command(fd, 0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_send_command(fd, 0x80); // --ratio
    ssd1306_send_command(fd, 0xA8); // Set multiplex ratio
    ssd1306_send_command(fd, 0x3F); // --height-1
    ssd1306_send_command(fd, 0xD3); // Set display offset
    ssd1306_send_command(fd, 0x00); // --offset
    ssd1306_send_command(fd, 0x40); // Set start line address
    ssd1306_send_command(fd, 0x8D); // Charge pump setting
    ssd1306_send_command(fd, 0x14); // --enable
    ssd1306_send_command(fd, 0x20); // Set memory addressing mode
    ssd1306_send_command(fd, 0x00); // --horizontal
    ssd1306_send_command(fd, 0xA1); // Set segment re-map
    ssd1306_send_command(fd, 0xC8); // Set COM output scan direction
    ssd1306_send_command(fd, 0xDA); // Set COM pins hardware configuration
    ssd1306_send_command(fd, 0x12); // --alternative
    ssd1306_send_command(fd, 0x81); // Set contrast control
    ssd1306_send_command(fd, 0xCF); // --contrast
    ssd1306_send_command(fd, 0xD9); // Set pre-charge period
    ssd1306_send_command(fd, 0xF1); // --period
    ssd1306_send_command(fd, 0xDB); // Set VCOM deselect level
    ssd1306_send_command(fd, 0x40); // --level
    ssd1306_send_command(fd, 0xA4); // Display all points off
    ssd1306_send_command(fd, 0xA6); // Set normal display
    ssd1306_send_command(fd, 0xAF); // Display on

    ssd1306_clear_display(fd);

    return 0;
}

// Send a command to the SSD1306
int ssd1306_send_command(int fd, uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;

    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }
    return 0;
}

// Send data to the SSD1306
int ssd1306_send_data(int fd, uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;

    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Clear the display
int ssd1306_clear_display(int fd) {
    for (int i = 0; i < (SSD1306_WIDTH * SSD1306_HEIGHT) / 8; i++) {
        ssd1306_send_data(fd, 0x00);
    }
    return 0;
}

