int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set pixel colour to red
        set_pixel_colour(1, 0, 0);
        gpioDelay(10000); // 0.01 seconds

        // Set pixel colour to green
        set_pixel_colour(0, 1, 0);
        gpioDelay(10000); // 0.01 seconds

        // Set pixel colour to blue
        set_pixel_colour(0, 0, 1);
        gpioDelay(10000); // 0.01 seconds

        // Set pixel colour to white
        set_pixel_colour(1, 1, 1);
        gpioDelay(10000); // 0.01 seconds

        // Set pixel colour to off
        set_pixel_colour(0, 0, 0);
        gpioDelay(10000); // 0.01 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();

    return 0;
}

