    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
