        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop: Set pins high, wait, set pins low, wait
    while (1) {
        // Set pins high
        for (int i = 0; i < num_pins; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
