// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADS1115
int init_ads1115(int fd) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    uint8_t buf[3];

    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to ADS1115 config register");
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc(int fd) {
    uint8_t buf[1];
    uint8_t read_buf[2];
    int16_t adc_value;

    // Set the register to read from (conversion register)
    buf[0] = ADS1115_REG_CONVERT;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to ADS1115 conversion register");
        return -1;
    }

    // Read two bytes from the conversion register
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from ADS1115 conversion register");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t adc_value = read_adc(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        printf("ADC Value: %d\n", adc_value);
        usleep(200000); // Wait 200ms
    }

    return 0;
}

