    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line as output */
    ret = gpiod_line_request_output(line, "my_gpio_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (1) {
        /* Set GPIO value */
        ret = gpiod_line_set_value(line, current_value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        /* Print GPIO value */
        printf("GPIO %d set to %d\n", GPIO_PIN, current_value);

        /* Toggle value */
        current_value = !current_value;

        /* Wait 60 seconds */
        sleep(60);
