        int16_t accel_z = read_word(i2c_fd, ACCEL_ZOUT_H);
        int16_t gyro_x = read_word(i2c_fd, GYRO_XOUT_H);
        int16_t gyro_y = read_word(i2c_fd, GYRO_YOUT_H);
        int16_t gyro_z = read_word(i2c_fd, GYRO_ZOUT_H);

        if (accel_x == -1 || accel_y == -1 || accel_z == -1 || gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        printf("AccelX: %d, AccelY: %d, AccelZ: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
