#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define GPIO_14 14
#define GPIO_15 15

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line14, *line15;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line14) {
        gpiod_line_release(line14);
    }
    if (line15) {
        gpiod_line_release(line15);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }
    return value;
}

// Function to report GPIO state
void report_gpio_state(int gpio14_value, int gpio15_value) {
    printf("GPIO 14: %d, GPIO 15: %d\n", gpio14_value, gpio15_value);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO lines
    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_14);
        gpiod_chip_close(chip);
        return 1;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_15);
        gpiod_chip_close(chip);
        gpiod_line_release(line14);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line14, "gpio14_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_14);
        gpiod_chip_close(chip);
        gpiod_line_release(line14);
        gpiod_line_release(line15);
        return 1;
    }

    if (gpiod_line_request_output(line15, "gpio15_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_15);
        gpiod_chip_close(chip);
        gpiod_line_release(line14);
        gpiod_line_release(line15);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 14 to HIGH
        if (set_gpio_value(line14, 1) < 0) {
            signal_handler(SIGINT);
        }

        // Set GPIO 15 to LOW
        if (set_gpio_value(line15, 0) < 0) {
            signal_handler(SIGINT);
        }

        // Get GPIO values
        int gpio14_value = get_gpio_value(line14);
        int gpio15_value = get_gpio_value(line15);

        if (gpio14_value < 0 || gpio15_value < 0) {
            signal_handler(SIGINT);
        }

        // Report GPIO state
        report_gpio_state(gpio14_value, gpio15_value);

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO 14 to LOW
        if (set_gpio_value(line14, 0) < 0) {
            signal_handler(SIGINT);
        }

        // Set GPIO 15 to HIGH
        if (set_gpio_value(line15, 1) < 0) {
            signal_handler(SIGINT);
        }

        // Get GPIO values
        gpio14_value = get_gpio_value(line14);
        gpio15_value = get_gpio_value(line15);

        if (gpio14_value < 0 || gpio15_value < 0) {
            signal_handler(SIGINT);
        }

        // Report GPIO state
        report_gpio_state(gpio14_value, gpio15_value);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>

// Configuration
#define MQTT_BROKER "localhost" // Change to your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "environmental/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel to read
#define VALID_MIN 0.0
#define VALID_MAX 100.0
#define READ_INTERVAL_MS 10 // 10 milliseconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
int validate_reading(float voltage);
char* format_payload(float voltage);
int publish_data(const char *payload);
void signal_handler(int sig);
int mqtt_connect_and_publish();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (3.3 / 1024.0);
}

// Function to validate sensor reading
int validate_reading(float voltage) {
    if (voltage >= VALID_MIN && voltage <= VALID_MAX) {
        return 1; // Valid
    } else {
        fprintf(stderr, "Error: Invalid sensor reading: %.2f\n", voltage);
        return 0; // Invalid
    }
}

// Function to format data payload
char* format_payload(float voltage) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char *payload = malloc(100 * sizeof(char)); // Allocate memory for the payload
    if (payload == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    snprintf(payload, 100, "{\"timestamp\": \"%s\", \"voltage\": %.2f}", timestamp, voltage);
    return payload;
}

// Function to publish data to MQTT broker
int publish_data(const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int mqtt_connect_and_publish() {
    int rc;

    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not start MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (mqtt_connect_and_publish() != 0) {
        fprintf(stderr, "Error: MQTT connection failed, exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float voltage = adc_to_voltage(adc_value);

        if (validate_reading(voltage)) {
            char *payload = format_payload(voltage);
            if (payload != NULL) {
                if (publish_data(payload) != 0) {
                    fprintf(stderr, "Error: Failed to publish data\n");
                }
                free(payload); // Free the allocated memory
            }
        }

        gpioDelay(READ_INTERVAL_MS * 1000); // Delay for 10 milliseconds
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

