#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum valid distance in cm
#define MAX_DISTANCE 400.0    // Maximum valid distance in cm
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance()
{
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;
    float distance;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger high\n");
        return -1.0;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1.0;
    }

    // Measure the echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go high with timeout
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go low with timeout
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    distance = (float)pulse_width_ns / 1000.0 * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to validate distance
int validate_distance(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to report distance
void report_distance(float distance)
{
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        printf("Error: Could not measure distance\n");
    }
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get line handles for trigger and echo pins
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return 1;
    }

    // Request lines for output and input respectively
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float distance = measure_distance();
        if (distance >= 0) {
            if (validate_distance(distance)) {
                report_distance(distance);
            }
        } else {
            report_distance(-1.0); // Report error
        }
        usleep(100000); // 0.1 seconds
    }

    // Release GPIO lines and close chip
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

