#define MQTT_TOPIC "home/sensor/temperature"
#define DHT22_GPIO 4
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int sig);
int read_dht22(int gpio, float *temperature, float *humidity);
int publish_mqtt(const char *topic, const char *payload);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting gracefully...\n");
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int result = 0;
    int i;
    int data[5] = {0, 0, 0, 0, 0};

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            return -1;
        }
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal\n");
            return -1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data bit start\n");
                return -1;
            }
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data bit end\n");
                return -1;
            }
        }
        long end = gpioTick();

        // Determine if it's a 0 or a 1 based on the pulse length
        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

// Function to publish data to MQTT broker
int publish_mqtt(const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        float temperature, humidity;
        char payload[50];

        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            // Format the payload
            snprintf(payload, sizeof(payload), "Temperature: %.1f C, Humidity: %.1f %%", temperature, humidity);

            // Publish the data
            if (publish_mqtt(MQTT_TOPIC, payload) != 0) {
                fprintf(stderr, "Failed to publish data\n");
            } else {
                printf("Published: %s\n", payload);
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

