#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range to 1,000,000
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM control on GPIO %d (BCM). Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // 0% duty cycle
        duty_cycle = 0;
        gpioPWM(GPIO_PIN, duty_cycle);
        printf("Duty cycle: %d%%\n", duty_cycle);
        gpioDelay(5000000); // 5 seconds

        // 50% duty cycle
        duty_cycle = 500000;
        gpioPWM(GPIO_PIN, duty_cycle);
        printf("Duty cycle: %d%%\n", duty_cycle);
        gpioDelay(5000000); // 5 seconds

        // 100% duty cycle
        duty_cycle = 1000000;
        gpioPWM(GPIO_PIN, duty_cycle);
        printf("Duty cycle: %d%%\n", duty_cycle);
        gpioDelay(5000000); // 5 seconds
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 100000       // Timeout in microseconds (0.1 seconds)

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Function prototypes
int init_gpio(void);
double measure_distance(void);
void cleanup_gpio(int signum);

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    cleanup_gpio(signum);
    exit(0);
}

// Initialize GPIO pins
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line for trigger pin
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line for echo pin
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    struct gpiod_line_request_config trigger_config;
    trigger_config.consumer = "hc-sr04-trigger";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(trigger_line, &trigger_config, 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    // Request echo line as input
    struct gpiod_line_request_config echo_config;
    echo_config.consumer = "hc-sr04-echo";
    echo_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(echo_line, &echo_config, 0) < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Measure distance using HC-SR04
double measure_distance(void) {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;

    // Trigger the sensor
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 us trigger pulse
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo to start
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if ((end_ns - start_ns) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }

    // Measure echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if ((end_ns - start_ns) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    double distance = (pulse_width_ns / 1000.0) * (SPEED_OF_SOUND / 2.0);

    return distance;
}

// Cleanup GPIO pins
void cleanup_gpio(int signum) {
    printf("Cleaning up GPIO...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (1) {
        double distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error measuring distance\n");
        }

        usleep(200000); // 0.2 seconds
    }

    return 0;
}

