// Function prototypes
int read_ads1115(int i2c_handle);
int publish_mqtt(int sensor_id, int reading);
void signal_handler(int sig);
int setup();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int i2c_handle;
} sensor_data_t;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read from ADS1115
int read_ads1115(int i2c_handle) {
    char buf[2];
    int16_t reading;

    // Read the conversion register
    if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    reading = (buf[0] << 8) | buf[1];

    // Sign extend if necessary
    if (reading & 0x8000) {
        reading |= 0xFFFF0000;
    }

    return reading;
}

// Function to publish to MQTT
int publish_mqtt(int sensor_id, int reading) {
    char payload[50];
    int rc;

    snprintf(payload, sizeof(payload), "{\"sensor_id\": %d, \"reading\": %d}", sensor_id, reading);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C handles for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, ADS1115_ADDR + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device %d: %s\n", i, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        cleanup();
        return -1;
    }

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60)) {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);

    return 0;
}

// Cleanup function
void cleanup() {
    // Close I2C handles
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }

    // Disconnect from MQTT broker
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    int reading_count = 0;
    while (!terminate && reading_count < 10) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int reading = read_ads1115(i2c_handles[i]);
            if (reading != -1) {
                if (publish_mqtt(i, reading) != 0) {
                    fprintf(stderr, "Error publishing sensor %d\n", i);
                }
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
        reading_count++;
    }

    cleanup();
    return 0;
}

