// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_word_2c(int i2c_handle, uint8_t reg)
{
    char buf[1];
    char data[2];
    int16_t value;

    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return 0; // Or some error value
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return 0; // Or some error value
    }

    value = (data[0] << 8) | data[1];
    return value;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6050
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0; // Clear sleep bit
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = read_word_2c(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_word_2c(i2c_handle, ACCEL_YOUT_H);
        int16_t accel_z = read_word_2c(i2c_handle, ACCEL_ZOUT_H);

        // Read gyroscope data
        int16_t gyro_x = read_word_2c(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_word_2c(i2c_handle, GYRO_YOUT_H);
        int16_t gyro_z = read_word_2c(i2c_handle, GYRO_ZOUT_H);

        // Print the data
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Wait 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

