    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read temperature and pressure data from the BMP280
int read_bmp280_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    uint8_t reg_addr = BMP280_REG_PRESS_MSB;

    // Set the BMP280 to forced mode
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x37) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Failed to set forced mode\n");
        return -1;
    }

    // Wait for the measurement to complete (adjust as needed)
    usleep(10000); // 10ms

    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address for data");
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    int32_t raw_pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    int32_t raw_temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    // Temperature compensation
    double var1 = (double)raw_temperature / 16384.0 - (double)calib.dig_T1 / 1024.0;
    var1 = var1 * ((double)calib.dig_T2);
    double var2 = ((double)raw_temperature / 131072.0 - (double)calib.dig_T1 / 8192.0);
    var2 = var2 * var2 * (double)calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (float)(t_fine / 5120.0);

    // Pressure compensation
    double var3 = (double)t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * (double)calib.dig_P6 / 32768.0;
    var4 = var4 + var3 * (double)calib.dig_P5 * 2.0;
    var4 = (var4 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    double var5 = (double)calib.dig_P3 * var3 * var3 / 524288.0;
    var5 = var5 + (double)calib.dig_P2 * var3 / 524288.0;
    var5 = (1.0 + var5 / 32768.0) * (double)calib.dig_P1;
    double p = 1048576.0 - (double)raw_pressure;
    p = (p - var4 / 4096.0) * 6250.0 / var5;
    var3 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var4 = p * (double)calib.dig_P8 / 32768.0;
    *pressure = (float)(p + (var3 + var4 + (double)calib.dig_P7) / 16.0);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Check BMP280 ID
    uint8_t chip_id;
    if (i2c_read_reg(i2c_fd, BMP280_REG_ID, &chip_id) != 0) {
        fprintf(stderr, "Failed to read BMP280 ID\n");
        close(i2c_fd);
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect BMP280 ID: 0x%02X\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float temperature, pressure;
    while (!stop_flag) {
        if (read_bmp280_data(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

