#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS 8
#define MQTT_BROKER "localhost" // Change to your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/automation/sensors"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define SAMPLE_INTERVAL_MS 5000 // 5 seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int publish_sensor_data(int channel, int value);
void signal_handler(int sig);
int mqtt_connect_and_publish(int channel, int value);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT
int publish_sensor_data(int channel, int value) {
    char topic[100];
    snprintf(topic, sizeof(topic), "%s/channel%d", MQTT_TOPIC, channel);

    char payload[20];
    snprintf(payload, sizeof(payload), "%d", value);

    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Function to connect to MQTT broker and publish data
int mqtt_connect_and_publish(int channel, int value) {
    int ret;

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = publish_sensor_data(channel, value);
    if (ret != 0) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < MCP3008_CHANNELS; channel++) {
            int adc_value = read_mcp3008(channel);
            if (adc_value >= 0) {
                if (mqtt_connect_and_publish(channel, adc_value) != 0) {
                    fprintf(stderr, "Error publishing data for channel %d\n", channel);
                }
            } else {
                fprintf(stderr, "Error reading channel %d\n", channel);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <string.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG
#define IMAGE_FILENAME "captured_image.jpg"

struct buffer {
    void   *start;
    size_t  length;
};

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer *buffers;
    unsigned int n_buffers;
    unsigned int i;
    FILE *fp;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return 1;
    }

    // Allocate memory for buffers
    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return 1;
    }

    // Map the buffer
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            close(fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Queue the buffer
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        free(buffers);
        return 1;
    }

    // Dequeue the buffer
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        close(fd);
        free(buffers);
        return 1;
    }

    // Save the image to file
    fp = fopen(IMAGE_FILENAME, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        close(fd);
        free(buffers);
        return 1;
    }

    fwrite(buffers[0].start, buffers[0].length, 1, fp);
    fclose(fp);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
