// Sensor data structure
typedef struct {
    int sensor_id;
    float temperature;
    float humidity;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_fd = -1;             // I2C file descriptor
volatile sig_atomic_t running = 1; // Flag to control the main loop

// Function prototypes
int init_i2c(const char *bus, int addr);
int write_pcf8574(int fd, uint8_t data);
void generate_sensor_data(sensor_data_t *sensors, int num_sensors);
void display_data(int fd, const sensor_data_t *sensors, int num_sensors);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Write data to PCF8574
int write_pcf8574(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Generate random sensor data
void generate_sensor_data(sensor_data_t *sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].sensor_id = i + 1;
        sensors[i].temperature = 20.0 + (float)(rand() % 100) / 10.0; // 20.0 to 30.0
        sensors[i].humidity = 40.0 + (float)(rand() % 60) / 10.0;    // 40.0 to 50.0
        sensors[i].pressure = 980.0 + (float)(rand() % 20) / 10.0;   // 980.0 to 990.0
    }
}

// Display sensor data on PCF8574 (simplified representation)
void display_data(int fd, const sensor_data_t *sensors, int num_sensors) {
    char buffer[16]; // Buffer to hold the display string
    snprintf(buffer, sizeof(buffer), "S%d:%.1f,%.1f,%.1f",
             sensors[0].sensor_id, sensors[0].temperature, sensors[0].humidity, sensors[0].pressure);

    // Convert the string to a uint8_t array (simplified representation)
    uint8_t display_data[1] = {0}; // Assuming only one byte is used for display
    for (int i = 0; i < strlen(buffer); i++) {
        display_data[0] |= (buffer[i] & 0x7F) << (i * 6); // Map characters to 6-bit segments (simplified)
    }

    if (write_pcf8574(fd, display_data[0]) != 0) {
        fprintf(stderr, "Error displaying data\n");
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, PCF8574_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    sensor_data_t sensors[NUM_SENSORS];

    // Main loop
    while (running) {
        // Generate sensor data
        generate_sensor_data(sensors, NUM_SENSORS);

        // Display data
        display_data(i2c_fd, sensors, NUM_SENSORS);

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

