#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void report_state(double distance);
void cleanup_gpio(int signal);

// Signal handler for Ctrl+C
void cleanup_gpio(int signal) {
    printf("\nCleaning up GPIO and exiting...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error: Could not get trigger line %d\n", TRIGGER_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error: Could not get echo line %d\n", ECHO_PIN);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: Could not request trigger line as output\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: Could not request echo line as input\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Send a 10us trigger pulse
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    int timeout = 100000; // 100ms timeout
    int count = 0;

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(echo_line) == 0 && count < timeout) {
        usleep(1); // Check every microsecond
        count++;
    }

    if (count >= timeout) {
        fprintf(stderr, "Error: Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low
    count = 0;
    while (gpiod_line_get_value(echo_line) == 1 && count < timeout) {
        usleep(1); // Check every microsecond
        count++;
    }

    if (count >= timeout) {
        fprintf(stderr, "Error: Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    long pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * 0.0343) / 2;
}

// Report the distance to standard output
void report_state(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main(void) {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup_gpio);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            report_state(distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse width\n");
        }

        sleep(1); // Wait 1 second
    }

    return 0;
}

