#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define PCF8574_ADDR 0x20     // PCF8574 I2C address
#define NUM_SENSORS 4         // Number of sensors to simulate

// Global variables
int i2c_fd = -1;             // I2C file descriptor
volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int value;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int write_pcf8574(int fd, unsigned char data);
void generate_sensor_data(sensor_data_t *data, int num_sensors);
void display_data(int fd, sensor_data_t *data, int num_sensors);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        stop_flag = 1;
    }
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Write data to PCF8574
int write_pcf8574(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Generate simulated sensor data
void generate_sensor_data(sensor_data_t *data, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        data[i].sensor_id = i + 1;
        data[i].value = rand() % 100; // Simulate value between 0 and 99
    }
}

// Display sensor data on PCF8574
void display_data(int fd, sensor_data_t *data, int num_sensors) {
    unsigned char display_data[num_sensors];

    // Convert sensor values to display data (example: values > 50 set bit)
    for (int i = 0; i < num_sensors; i++) {
        display_data[i] = (data[i].value > 50) ? 1 : 0; // Simple threshold
    }

    // Send data to PCF8574
    unsigned char output_data = 0;
    for (int i = 0; i < num_sensors; i++) {
        output_data |= (display_data[i] << i);
    }

    if (write_pcf8574(fd, output_data) != 0) {
        fprintf(stderr, "Error displaying data.\n");
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, PCF8574_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data[NUM_SENSORS];

    // Main loop
    while (!stop_flag) {
        // Generate sensor data
        generate_sensor_data(sensor_data, NUM_SENSORS);

        // Display data
        display_data(i2c_fd, sensor_data, NUM_SENSORS);

        // Wait for a short period
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Program terminated.\n");
    return 0;
}

