#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM duty cycle range
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles
        gpioPWM(PWM_PIN_1, MIN_DUTY_CYCLE);
        gpioPWM(PWM_PIN_2, MAX_DUTY_CYCLE);
        gpioPWM(PWM_PIN_3, 128);

        // Report state
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", PWM_PIN_1, MIN_DUTY_CYCLE, PWM_PIN_2, MAX_DUTY_CYCLE, PWM_PIN_3, 128);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

