#define GPIO_PIN_18 18
#define GPIO_PIN_27 27

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18, *line27;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);

    if (!line17 || !line18 || !line27) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line17, "10", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line18, "10", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line27, "10", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO values
    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_set_value(line18, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 18");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_set_value(line27, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 27");
        gpiod_chip_close(chip);
        return 1;
    }

    // Print GPIO values
    printf("GPIO 17: %d\n", gpiod_line_get_value(line17));
    printf("GPIO 18: %d\n", gpiod_line_get_value(line18));
    printf("GPIO 27: %d\n", gpiod_line_get_value(line27));

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x44
#define I2C_BUS 1

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31
int read_sht31(float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x24, 0x00}; // High repeatability measurement command
    uint8_t data[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for high repeatability)

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC Check
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    // Validity check
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor reading: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (1) {
        if (read_sht31(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins to be used
const int gpio_pins[] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for libgpiod resources
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[10] = {NULL}; // Array to hold line pointers

// Function prototypes
int set_gpio_output(int gpio, int value);
void cleanup(int signum);

// Signal handler for Ctrl+C
void cleanup(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Release GPIO lines
    for (int i = 0; i < num_pins; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the GPIO output value
int set_gpio_output(int gpio, int value) {
    int ret;
    struct timespec delay = {0, 100000000}; // 100ms delay

    ret = gpiod_line_set_value(lines[gpio], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", gpio, gpiod_line_perror(lines[gpio]));
        return -1;
    }

    nanosleep(&delay, NULL);

    return 0;
}

int main() {
    int i, ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_perror(chip));
        return 1;
    }

    // Get line handles for each GPIO pin
    for (i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", gpio_pins[i], gpiod_chip_perror(chip));
            cleanup(0); // Clean up and exit
            return 1;
        }

        // Request the line as an output
        ret = gpiod_line_request_output(lines[i], "my_program", 0); // Initial value 0
        if (ret < 0) {
            fprintf(stderr, "Error requesting line for GPIO %d as output: %s\n", gpio_pins[i], gpiod_line_perror(lines[i]));
            cleanup(0); // Clean up and exit
            return 1;
        }
    }

    // Main loop: Set each GPIO high, then low
    while (1) {
        for (i = 0; i < num_pins; i++) {
            if (set_gpio_output(i, 1) != 0) {
                cleanup(0);
                return 1;
            }
            printf("GPIO %d set HIGH\n", gpio_pins[i]);
        }

        for (i = 0; i < num_pins; i++) {
            if (set_gpio_output(i, 0) != 0) {
                cleanup(0);
                return 1;
            }
            printf("GPIO %d set LOW\n", gpio_pins[i]);
        }
    }

    return 0; // This line will never be reached due to the infinite loop
}

