#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM duty cycle to 50% (128/255)
    gpioPWM(PWM_PIN_1, 128);
    gpioPWM(PWM_PIN_2, 128);
    gpioPWM(PWM_PIN_3, 128);
    gpioPWM(PWM_PIN_4, 128);

    // Report the state applied to standard output
    printf("PWM_PIN_1=%d PWM_PIN_2=%d PWM_PIN_3=%d PWM_PIN_4=%d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
    printf("PWM duty cycle: 50%% (128/255)\n");
    printf("PWM frequency: 1 kHz\n");

    // Clean up and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

static struct gpiod_chip *chip;
static struct gpiod_line *line2, *line3;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line for GPIO 2
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 2)");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 3
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        perror("gpiod_chip_get_line (GPIO 3)");
        gpiod_chip_close(chip);
        gpiod_line_release(line2);
        return 1;
    }

    // Request GPIO 2 as output
    ret = gpiod_line_request_output(line2, "toggle_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        gpiod_chip_close(chip);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return 1;
    }

    // Request GPIO 3 as output
    ret = gpiod_line_request_output(line3, "toggle_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        gpiod_chip_close(chip);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            break;
        }
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            break;
        }
        printf("GPIO 2: 1, GPIO 3: 0\n");

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            break;
        }
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            break;
        }
        printf("GPIO 2: 0, GPIO 3: 1\n");

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Release GPIO lines
    gpiod_line_release(line2);
    gpiod_line_release(line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

