#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins (BCM numbering)
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define GPIO_17 17

// Chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2, *line3, *line5, *line17;

// Function prototypes
int set_gpio_output(struct gpiod_line *line, int value);
int report_gpio_state(struct gpiod_line *line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line5) gpiod_line_release(line5);
    if (line17) gpiod_line_release(line17);

    // Close chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to set GPIO output value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }

    return 0;
}

// Function to report GPIO state
int report_gpio_state(struct gpiod_line *line) {
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", gpiod_line_name(line));
        return -1;
    }

    printf("%s: %d\n", gpiod_line_name(line), value);
    return 0;
}

int main() {
    int ret;
    struct timespec sleep_time;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return 1;
    }

    // Get GPIO lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line2 || !line3 || !line5 || !line17) {
        fprintf(stderr, "Error getting GPIO line\n");
        if(line2) gpiod_line_release(line2);
        if(line3) gpiod_line_release(line3);
        if(line5) gpiod_line_release(line5);
        if(line17) gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(line2, "gpio2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line 2 as output\n");
        gpiod_line_release(line2);
