// Define GPIO pins for RGB (BCM numbering)
#define RED_PIN   18
#define GREEN_PIN 23
#define BLUE_PIN  24

// Function prototypes
void set_red(int value);
void set_green(int value);
void set_blue(int value);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    gpioTerminate();
    exit(0);
}

// Function to set the red LED value
void set_red(int value) {
    gpioWrite(RED_PIN, value);
}

// Function to set the green LED value
void set_green(int value) {
    gpioWrite(GREEN_PIN, value);
}

// Function to set the blue LED value
void set_blue(int value) {
    gpioWrite(BLUE_PIN, value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop to cycle through colors
    for (int i = 0; i < 3; i++) {
        // Red
        set_red(1);
        set_green(0);
        set_blue(0);
        gpioDelay(50000); // 50ms

        // Green
        set_red(0);
        set_green(1);
        set_blue(0);
        gpioDelay(50000); // 50ms

        // Blue
        set_red(0);
        set_green(0);
        set_blue(1);
        gpioDelay(50000); // 50ms

        // Yellow
        set_red(1);
        set_green(1);
        set_blue(0);
        gpioDelay(50000); // 50ms

        // Purple
        set_red(1);
        set_green(0);
        set_blue(1);
        gpioDelay(50000); // 50ms

        // Cyan
        set_red(0);
        set_green(1);
        set_blue(1);
        gpioDelay(50000); // 50ms

        // White
        set_red(1);
        set_green(1);
        set_blue(1);
        gpioDelay(50000); // 50ms

        // Off
        set_red(0);
        set_green(0);
        set_blue(0);
        gpioDelay(50000); // 50ms
    }

    // Cleanup and exit
    cleanup(0);

    return 0;
}

