    fprintf(stderr, "Error: DS18B20 device not found\n");
    return -1;
}

// Function to read the temperature from the DS18B20
float read_temperature() {
    char device_path[100];
    FILE *fp;
    char line[256];
    char *token;
    float temperature = -999.0; // Default error value

    snprintf(device_path, sizeof(device_path), "%s/%s/%s", W1_DEVICES_DIR, w1_device_id, W1_SLAVE_FILE);

    fp = fopen(device_path, "r");
    if (fp == NULL) {
        perror("Error opening " W1_SLAVE_FILE);
        return -999.0;
    }

    // Read the first line (crc check)
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading first line from %s\n", W1_SLAVE_FILE);
        return -999.0;
    }

    // Check CRC
    if (strstr(line, "YES") == NULL) {
        fclose(fp);
        fprintf(stderr, "CRC check failed\n");
        return -999.0;
    }

    // Read the second line (temperature)
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading second line from %s\n", W1_SLAVE_FILE);
        return -999.0;
    }

    fclose(fp);

    // Parse the temperature from the second line
    token = strstr(line, "t=");
    if (token != NULL) {
        long temp_milli_celsius = strtol(token + 2, NULL, 10);
        temperature = (float)temp_milli_celsius / 1000.0;
    } else {
        fprintf(stderr, "Error parsing temperature from %s\n", W1_SLAVE_FILE);
        return -999.0;
    }

    return temperature;
}

int main() {
    int i;
    float temperature;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Find the DS18B20 device
    if (find_ds18b20_device() != 0) {
        fprintf(stderr, "DS18B20 device not found. Exiting.\n");
        return 1;
    }

    // Read temperature every 5 seconds for 3 times
    for (i = 0; i < 3 && keep_running; i++) {
        temperature = read_temperature();
        if (temperature != -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(5);
    }

    printf("Exiting.\n");
    return 0;
}

