// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define GPIO_CHIP "gpiochip0"

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 100000       // Timeout in microseconds (0.1 seconds)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    terminate = 1;
}

// Function to measure distance using HC-SR04
float measure_distance()
{
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        return -1.0;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
        return -1.0;
    }

    // Measure the echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go high with timeout
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if (end_ns - start_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0; // Timeout
        }
        timeout = 1;
    }
    if (!timeout) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        pulse_width_ns = end_ns - start_ns;

        // Wait for echo to go low with timeout
        timeout = 0;
        while (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
            if (end_ns - start_ns > TIMEOUT_US * 1000) {
                fprintf(stderr, "Timeout waiting for echo low\n");
                return -1.0; // Timeout
            }
            timeout = 1;
        }
        if (!timeout) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
            pulse_width_ns = end_ns - start_ns;

            // Calculate distance in centimeters
            return (float)pulse_width_ns / 1000.0 * SPEED_OF_SOUND / 2.0;
        } else {
            return -1.0; // Timeout
        }
    } else {
        return -1.0; // Timeout
    }
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line handles for trigger and echo pins
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return 1;
    }

    // Request lines for output and input respectively
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // Clean up and exit
    printf("Exiting...\n");
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

