#include <unistd.h>

// Define GPIO pins
#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d. Must be between 0 and 100.\n", duty_cycle);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, duty_cycle);
    return 0; // Indicate success
}

// Function to print the current PWM duty cycle for all GPIO pins
void print_pwm_state() {
    printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
           PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1),
           PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2),
           PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles
        if (set_pwm_duty_cycle(PWM_PIN_1, 25) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, 50) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, 75) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Print PWM state
        print_pwm_state();

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

