#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define TIMEOUT_US 100000 // 100ms

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Delay 1 us
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Delay 1 us
    }

    // Wait for the DHT22 to pull the line low again
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "DHT22 timeout waiting for data signal\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Delay 1 us
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the DHT22 to pull the line high
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            timeout++;
            if (timeout > TIMEOUT_US) {
                fprintf(stderr, "DHT22 timeout waiting for data bit start\n");
                return -1; // Timeout
            }
            gpioDelay(1); // Delay 1 us
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            timeout++;
            if (timeout > TIMEOUT_US) {
                fprintf(stderr, "DHT22 timeout waiting for data bit end\n");
                return -1; // Timeout
            }
            gpioDelay(1); // Delay 1 us
        }
        long end = gpioTick();
        long duration = end - start;

        // Determine if it's a 0 or a 1 based on the pulse length
        if (duration > 40) { // Experimentally determined threshold
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) | data[3]) & 0x7FFF) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int retries = 0;
    float temperature, humidity;

    while (!terminate && retries < MAX_RETRIES) {
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            retries = 0; // Reset retries on success
        } else {
            fprintf(stderr, "DHT22 read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
    }

    gpioTerminate();
    return 0;
}

