#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read data from MAX31855
int read_max31855(int fd, float *internal_temp, float *thermocouple_temp, int *fault) {
    uint8_t tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract data from the received buffer
    int32_t raw_data = (rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3];

    // Check for fault
    *fault = (raw_data & 0x00000007);
    if (*fault) {
        fprintf(stderr, "MAX31855 Fault: ");
        if (*fault & 0x00000001) fprintf(stderr, "Open circuit, ");
        if (*fault & 0x00000002) fprintf(stderr, "Short to GND, ");
        if (*fault & 0x00000004) fprintf(stderr, "Short to VCC, ");
        fprintf(stderr, "\n");
        return -1; // Indicate an error
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out the sign bit and fault bits
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }
    *thermocouple_temp = thermocouple_data * 0.25;

    // Extract internal temperature (bits 15:4)
    int16_t internal_data = (raw_data >> 4) & 0x7FF; // Mask out the fault bits
    if (internal_data & 0x400) {
        internal_data |= 0xF800; // Sign extend if negative
    }
    *internal_temp = internal_data * 0.0625;

    return 0; // Success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return 1;
    }

    float internal_temp, thermocouple_temp;
    int fault;

    // Read and print data
    if (read_max31855(spi_fd, &internal_temp, &thermocouple_temp, &fault) == 0) {
        printf("Thermocouple Temperature: %.2f °C\n", thermocouple_temp);
        printf("Internal Temperature: %.2f °C\n", internal_temp);
    } else {
        fprintf(stderr, "Failed to read temperature data.\n");
        close(spi_fd);
        return 1;
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

