        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO17)");
        goto cleanup_chip;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        perror("gpiod_chip_get_line (GPIO18)");
        goto cleanup_line17;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line17, "toggle_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO17)");
        goto cleanup_line18;
    }

    ret = gpiod_line_request_output(line18, "toggle_output", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO18)");
        goto cleanup_line17_release;
    }

    // Main loop
    while (!terminate) {
        // Toggle GPIO 17
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            goto cleanup_line18_release;
        }
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO17)");
            goto cleanup_line18_release;
        }

        // Toggle GPIO 18
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
