#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins using BCM numbering
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 100000       // Timeout in microseconds (100ms)

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Function prototypes
int initialize_gpio(void);
double measure_distance(void);
void cleanup_gpio(int signum);

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    cleanup_gpio(signum);
    exit(signum);
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line for trigger pin
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line for echo pin
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    struct gpiod_line_request_config trigger_config;
    trigger_config.consumer = "hc-sr04-trigger";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(trigger_line, &trigger_config, 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    // Request echo line as input
    struct gpiod_line_request_config echo_config;
    echo_config.consumer = "hc-sr04-echo";
    echo_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(echo_line, &echo_config, 0) < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Function to measure distance using HC-SR04
double measure_distance(void) {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;

    // Trigger the sensor
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 us trigger pulse
    gpiod_line_set_value(trigger_line, 0);

    // Measure echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go high with timeout
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0; // Indicate timeout error
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for echo to go low with timeout
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0; // Indicate timeout error
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    // Calculate pulse width in nanoseconds
    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    double distance = (pulse_width_ns / 1000.0) * SPEED_OF_SOUND / 2000000000.0;

    return distance;
}

// Function to cleanup GPIO resources
void cleanup_gpio(int signum) {
    printf("Cleaning up GPIO resources...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("GPIO cleanup complete.\n");
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Measure distance
    double distance = measure_distance();

    // Report the result
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        fprintf(stderr, "Error measuring distance.\n");
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(0);

    return 0;
}

