// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04
#define VEML7700_WHITE_DATA 0x05

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to a VEML7700 register
int write_veml7700_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = value & 0xFF;       // LSB
    buf[2] = (value >> 8) & 0xFF; // MSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a VEML7700 register
int read_veml7700_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read LSB");
        return -1;
    }
    uint16_t lsb = buf[0];

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read MSB");
        return -1;
    }
    uint16_t msb = buf[0];

    *value = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure VEML7700 (example configuration: gain 2x, integration time 100ms)
    uint16_t config_value = 0x0000; // Default configuration
    if (write_veml7700_register(i2c_fd, VEML7700_CONFIG, config_value) < 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data, white_data;

        // Read ALS data
        if (read_veml7700_register(i2c_fd, VEML7700_ALS_DATA, &als_data) < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            break;
        }

        // Read White data
        if (read_veml7700_register(i2c_fd, VEML7700_WHITE_DATA, &white_data) < 0) {
            fprintf(stderr, "Failed to read White data\n");
            break;
        }

        // Print the readings
        printf("ALS: %u, White: %u\n", als_data, white_data);

        // Wait for 0.5 seconds
        usleep(500000); // 500000 microseconds = 0.5 seconds
    }

    // Clean up and exit
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;    // Read at least 0 characters
    tty.c_cc[VTIME] = 10;  // Wait for up to 1 second (10 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout or no data available
        }
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        return 0; // No data read
    }

    buffer[bytes_read] = '\0';
    return bytes_read;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = configure_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to configure UART. Exiting.\n");
        return 1;
    }

    char buffer[256];
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    printf("Reading data from UART port %s...\n", UART_PORT);

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
void cleanup_gpio(void);
double measure_distance(void);
int validate_distance(double distance);
void report_state(double distance);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Measure distance using HC-SR04
double measure_distance(void) {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        return -1.0;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
        return -1.0;
    }

    // Measure echo pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        if (start_ns - start_ns > TIMEOUT_US * 1000) {
            timeout = 1;
            break;
        }
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        if (end_ns - start_ns > TIMEOUT_US * 1000) {
            timeout = 1;
            break;
        }
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    pulse_width_ns = end_ns - start_ns;

    // Calculate distance in centimeters
    double distance = (pulse_width_ns / 1000.0) * SPEED_OF_SOUND / 2000000.0;

    return distance;
}

// Validate distance measurement
int validate_distance(double distance) {
    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Report the state to standard output
void report_state(double distance) {
    if (distance >= 0.0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        printf("Error: Could not read distance\n");
    }
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        double distance = measure_distance();

        if (distance >= 0.0 && validate_distance(distance)) {
            report_state(distance);
        } else {
            report_state(-1.0); // Report error
        }

        usleep(500000); // 0.5 seconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

