        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set to measure mode)
    if (i2c_write_reg(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to initialize ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    // Read acceleration data
    int16_t x, y, z;
    uint8_t x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_reg(i2c_fd, ADXL345_DATAX0);
    x1 = i2c_read_reg(i2c_fd, ADXL345_DATAX0 + 1);
    y0 = i2c_read_reg(i2c_fd, ADXL345_DATAX0 + 2);
    y1 = i2c_read_reg(i2c_fd, ADXL345_DATAX0 + 3);
    z0 = i2c_read_reg(i2c_fd, ADXL345_DATAX0 + 4);
    z1 = i2c_read_reg(i2c_fd, ADXL345_DATAX0 + 5);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        fprintf(stderr, "Failed to read acceleration data\n");
        close(i2c_fd);
        return 1;
    }

    x = (int16_t)((x1 << 8) | x0);
    y = (int16_t)((y1 << 8) | y0);
    z = (int16_t)((z1 << 8) | z0);

    // Print acceleration data
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    // Close I2C device
    close(i2c_fd);

    return 0;
}

