#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Flag that echo has started
        } else if (level == 0 && echo_received == 1) {
            echo_end_tick = tick;
            echo_received = 0; // Reset the flag
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo
        echo_received = 0; // Reset the flag
        echo_start_tick = 0;
        echo_end_tick = 0;

        // Set alert function for echo pin
        gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

        // Wait for echo or timeout
        int timeout_counter = 0;
        while (echo_end_tick == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_counter++;
        }

        // Calculate pulse width
        int pulse_width = 0;
        if (echo_end_tick > echo_start_tick) {
            pulse_width = echo_end_tick - echo_start_tick;
        } else if (echo_end_tick > 0 && echo_start_tick > 0) {
            pulse_width = (0xFFFFFFFF - echo_start_tick) + echo_end_tick; // Handle wrap-around
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Control LED based on distance
        if (distance < 20.0) {
            gpioWrite(LED_PIN, 1); // Turn on LED
        } else {
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Delay before next measurement
        gpioDelay(100); // 100ms delay
    }

    return 0;
}

