#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
void control_led(float distance);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!trigger_line || !echo_line || !led_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    struct gpiod_line_request_config config;
    config.consumer = "hc-sr04";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        perror("Error requesting trigger line");
        cleanup_gpio();
        return -1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        perror("Error requesting echo line");
        cleanup_gpio();
        return -1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting LED line");
        cleanup_gpio();
        return -1;
    }

    // Ensure trigger is low initially
    gpiod_line_set_value(trigger_line, 0);
    gpiod_line_set_value(led_line, 0);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    int timeout = 0;

    // Wait for echo to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    return (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Control the LED based on distance
void control_led(float distance) {
    if (distance < 20.0) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor and LED Control\n");

    while (!terminate) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            // Calculate the distance
            float distance = calculate_distance(pulse_width);

            // Control the LED
            control_led(distance);

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure pulse width\n");
        }

        // Wait for 0.1 seconds
        usleep(100000);
    }

    return 0;
}

