// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)
#define TCS34725_PDATA           (0x1C)
#define TCS34725_CONTROL         (0x0F)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10)  /* RGBC Enable */
#define TCS34725_ENABLE_WEN      (0x08)  /* Wait enable - Writing 1 activates the wait timer */
#define TCS34725_ENABLE_AEN      (0x02)  /* RGBC Enable - Writing 1 actives the ADC, 0 disables it */
#define TCS34725_ENABLE_PON      (0x01)  /* Power on - Writing 1 activates the internal oscillator, 0 disables it */

// Integration Time Options
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   /*  2.4ms - 1 cycle    - Max Count: 1024  */
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   /* 24ms  - 10 cycles   - Max Count: 10240 */
#define TCS34725_INTEGRATIONTIME_50MS   (0xEB)   /* 50ms  - 20 cycles   - Max Count: 20480 */
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)   /* 101ms - 42 cycles   - Max Count: 42592 */
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   /* 154ms - 64 cycles   - Max Count: 65535 */
#define TCS34725_INTEGRATIONTIME_238MS  (0x80)   /* 238ms - 128 cycles  - Max Count: 65535 */

// Gain Options
#define TCS34725_GAIN_1X                (0x00)   /* No gain  */
#define TCS34725_GAIN_4X                (0x01)   /* 4x gain  */
#define TCS34725_GAIN_16X               (0x02)   /* 16x gain */
#define TCS34725_GAIN_60X               (0x03)   /* 60x gain */

int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int tcs34725_init(int fd) {
    uint8_t id;
    uint8_t status;

    // Check device ID
    if (i2c_smbus_read_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ID) < 0) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    id = i2c_smbus_read_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id != 0x44) {
        fprintf(stderr, "Error: Invalid TCS34725 ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON): %s\n", strerror(errno));
        return -1;
    }
    usleep(3000); // Wait for power-on (3ms)

    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON+AEN): %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int tcs34725_read_data(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    *clear = i2c_smbus_read_word_data(fd, TCS34725_COMMAND_BIT | TCS34725_CDATA);
    *red   = i2c_smbus_read_word_data(fd, TCS34725_COMMAND_BIT | TCS34725_RDATA);
    *green = i2c_smbus_read_word_data(fd, TCS34725_COMMAND_BIT | TCS34725_GDATA);
    *blue  = i2c_smbus_read_word_data(fd, TCS34725_COMMAND_BIT | TCS34725_BDATA);

    if (*clear == -1 || *red == -1 || *green == -1 || *blue == -1) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int ret;
    uint16_t red, green, blue, clear;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (!stop_flag) {
        if (tcs34725_read_data(i2c_fd, &red, &green, &blue, &clear) == 0) {
            printf("R: %5d, G: %5d, B: %5d, C: %5d\n", red, green, blue, clear);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(500000); // 0.5 seconds
    }

    // Cleanup
    close(i2c_fd);
    printf("I2C device closed.\n");

    return 0;
}

