#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
void report_distance(float distance);
void cleanup_gpio(int signum);

// Signal handler for Ctrl+C
void cleanup_gpio(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Send a 10us trigger pulse
void trigger_pulse(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        return;
    }
    usleep(10); // 10 microseconds
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
    }
}

// Measure the pulse width on the echo pin
long measure_pulse_width(void) {
    struct timespec start, end;
    int timeout = 100000; // 100ms timeout
    int count = 0;

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(echo_line) == 0 && count < timeout) {
        usleep(1); // Check every microsecond
        count++;
    }

    if (count >= timeout) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low
    count = 0;
    while (gpiod_line_get_value(echo_line) == 1 && count < timeout) {
        usleep(1); // Check every microsecond
        count++;
    }

    if (count >= timeout) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    long pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (pulse_width * 0.0343) / 2;
}

// Report the distance to standard output
void report_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main(void) {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup_gpio);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (1) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            report_distance(distance);
        } else {
            fprintf(stderr, "Error: Could not measure pulse width\n");
        }

        usleep(500000); // 0.5 seconds
    }

    return 0;
}

