        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        /* Wait for a short time */
        usleep(500000); // 0.5 seconds
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

