#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_word_2c(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return 0;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read data");
        return 0;
    }
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t wake_up = 0x00;
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_word_2c(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_word_2c(i2c_fd, ACCEL_YOUT_H);
        int16_t accel_z = read_word_2c(i2c_fd, ACCEL_ZOUT_H);
        int16_t gyro_x  = read_word_2c(i2c_fd, GYRO_XOUT_H);
        int16_t gyro_y  = read_word_2c(i2c_fd, GYRO_YOUT_H);
        int16_t gyro_z  = read_word_2c(i2c_fd, GYRO_ZOUT_H);

        // Print the data
        printf("Accel X: %6d, Accel Y: %6d, Accel Z: %6d, Gyro X: %6d, Gyro Y: %6d, Gyro Z: %6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Wait for 1 second
        sleep(1);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

