#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    keep_running = 0;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 600000000}; // 0.6 seconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "my_gpio_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    int current_value = 0;
    while (keep_running) {
        // Set GPIO value
        ret = gpiod_line_set_value(line, current_value);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }

        // Print GPIO value
        printf("GPIO %d set to %d\n", GPIO_PIN, current_value);

        // Toggle value for next iteration
        current_value = !current_value;

        // Sleep for 0.6 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
